from pathlib import Path
import html,json
p=Path(__file__).resolve().parent;slides=[]
def S(ch,title,lead,body,source='Method / proposed engagement design',note='',cls=''):
 slides.append(dict(ch=ch,title=title,lead=lead,body=body,source=source,note=note,cls=cls))
def cols(*args):return '<div class="cols c'+str(len(args))+'">'+''.join('<div>'+x+'</div>' for x in args)+'</div>'
def box(k,t,b):return f'<div class="box"><span class="label">{k}</span><h3>{t}</h3><p>{b}</p></div>'
def table(head,rows):return '<table><thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def call(t):return '<div class="takeaway">'+t+'</div>'
def steps(items):return '<div class="flow">'+''.join(f'<div><span>{i+1:02}</span><h3>{t}</h3><p>{b}</p></div>' for i,(t,b) in enumerate(items))+'</div>'
A='Case A / Korean Bank · supplied April 2026 audit · reported observations, not a fresh audit'
B='Case B / Korean Insurance Company · supplied April 2026 audit · reported observations, not a fresh audit'
S('THE COMMERCIAL QUESTION','When customers ask AI,<br>does your expertise appear?','Fractional GEO, AEO & SEO leadership',cols('''<p class="intro">An operating programme for businesses that need to be found, understood and considered across search and AI answers.</p><div class="byline">Demand Journeys<br><small>Meng Liang Tan · Singapore</small></div><a class="button" href="#/1">Explore the case studies ↗</a>''','''<div class="cover-art"><div class="question">“Which provider fits my needs?”</div><div class="source-lines"><span>Your expertise</span><span>Public evidence</span><span>Customer context</span></div><div class="answer"><span>THE OPPORTUNITY</span><strong>A credible place<br>in the answer</strong></div><div class="final-node">Qualified consideration</div></div>'''),'Two anonymised diagnostic cases / proposed delivery programme / local review draft',cls='cover')
S('01 / WHY THIS WORK','Five problems worth solving','Start with the buyer decision that matters to your business.','<div class="problem-list">'+''.join(f'<a href="#/{n}"><b>0{i}</b><h3>{t}</h3><span>{b}</span><em>↗</em></a>' for i,n,t,b in [(1,5,'Our expertise is hard to find','Public information does not answer the buyer’s question.'),(2,9,'Our brand is described inconsistently','Facts, products and business units blur across sources.'),(3,13,'Our content is hard to use','Important answers sit behind technical or editorial barriers.'),(4,17,'We cannot measure AI visibility','Mentions, citations and commercial results get mixed together.'),(5,23,'The work has no clear owner','SEO, content, technology and approvals move separately.')])+'</div>')
S('01 / WHY THIS WORK','Visibility has to connect to a decision','A useful programme follows the buyer beyond the first answer.',steps([('Discover','Does a relevant question surface the business?'),('Understand','Are its facts and product conditions accurate?'),('Consider','Is it eligible for the buyer’s shortlist?'),('Act','Can the buyer reach a suitable next step?')])+cols(box('VISIBILITY SIGNAL','Presence in the answer','Track mentions, linked sources and factual accuracy separately.'),box('COMMERCIAL SIGNAL','Quality of the next step','Track qualified enquiries, quote starts or applications, then reconcile downstream outcomes.')),'Proposed measurement model / visibility alone does not establish incremental revenue')
S('01 / WHY THIS WORK','One programme, three connected disciplines','These are working definitions. The same page can support all three.',table(['Discipline','What I improve','What we inspect'],[['<b>SEO</b><br>Search engine optimisation','Discovery, index eligibility and organic landing-page performance.','Crawls, rendered pages, internal links, search data and conversions.'],['<b>AEO</b><br>Answer engine optimisation','How clearly a page resolves a specific question.','Direct answers, conditions, supporting evidence and useful next steps.'],['<b>GEO</b><br>Generative engine optimisation','How the business appears and is cited in generated responses.','Repeatable prompt panels, cited URLs and verified factual accuracy.']])+call('The supplied research uses “AIO” in several ways. This deck uses AEO for answer quality and treats agent integrations as a separate, optional workstream.'),'Framework adapted from supplied research / Google AI guidance [S1]')
S('02 / THE EVIDENCE','Two cases. Different constraints.','The work is diagnostic: identify the weak point, define the response and specify how to verify it.',cols(box('CASE A','Korean Bank','Limited discoverable first-party material, weak English coverage and missing markup in sampled pages.<br><br><b>Commercial question</b><br>Can a prospective customer resolve eligibility, product conditions and trust questions?'),box('CASE B','Korean Insurance Company','Fragmented properties, content-rendering concerns and stale English entity information.<br><br><b>Commercial question</b><br>Can a prospective customer distinguish the provider, understand coverage and reach the right quote journey?'))+call('Evidence boundary: the archive contains public-site observations, inferred risks and simulated answer estimates. It does not demonstrate a deployed programme or measured citation uplift.'),'Case A + Case B / April 2026 audit bundle methodology')
S('03 / CASE A · KOREAN BANK','The missing asset was usable public evidence','A recognised business can still leave important customer questions unanswered.',table(['Reported finding','Decision it obstructs','First validation step'],[['Limited coverage in the inspected sitemaps','Finding product, support and corporate information.','Compare sitemap entries with a crawl and the CMS inventory.'],['No English site found at the tested paths','Understanding eligibility and access in another language.','Map the actual audience, service capability and available pages.'],['No structured data detected in sampled HTML','Interpreting the provider and product consistently.','Inspect raw and rendered HTML across representative templates.'],['Thin entity and product explanations','Checking conditions and distinguishing facts from commentary.','Build a claim inventory with approved source references.']])+call('A short sitemap is a discovery clue. It is not a count of indexed pages, and it does not prove that the rest of the site is invisible.'),A+' / interpretation qualified using [S2]')
S('03 / CASE A · KOREAN BANK','Customer questions determine the content backlog','Choose pages by the decisions they support, then test whether those pages are found.',table(['Buyer intent','Example question','Proposed source page','Commercial next step'],[['Trust','How do I verify the institution and its disclosures?','Institution profile with dated official references.','Review approved disclosures.'],['Eligibility','Can a foreign resident apply?','Eligibility and documentation guide.','Check eligibility before applying.'],['Product choice','Which account fits my withdrawal needs?','Product comparison with limits, fees and conditions.','Visit the relevant product journey.'],['Service','How do I resolve an access or account issue?','Public support guide with verified service channels.','Reach the correct support route.']]),'Case A / content and prompt research; examples rewritten and anonymised')
S('03 / CASE A · KOREAN BANK','A source page earns its usefulness','The proposed content makes a claim understandable and maintainable.',cols('''<div class="specimen"><span class="label">ILLUSTRATIVE PAGE STRUCTURE</span><h3>Account eligibility and access</h3><p class="answer-copy">Eligibility depends on residency, identification and the selected product. Check the current requirements before beginning an application.</p><dl><dt>Who can apply?</dt><dd>Approved eligibility criteria and exceptions.</dd><dt>What is required?</dt><dd>Documents, verification steps and service limitations.</dd><dt>What changes the answer?</dt><dd>Product conditions and effective dates.</dd></dl><div class="specimen-foot">Reviewed by product owner · source reference · review date</div></div>''','''<ol class="numbered"><li><b>A direct answer</b><span>Explain the question before presenting the brand.</span></li><li><b>Conditions beside the claim</b><span>Keep limits and exclusions in the same reading path.</span></li><li><b>Evidence people can inspect</b><span>Link to the governing product and disclosure sources.</span></li><li><b>A useful next action</b><span>Take eligible visitors to the appropriate application or support route.</span></li></ol>'''), 'Case A / proposed editorial template; illustrative wording, not financial product advice')
S('03 / CASE A · KOREAN BANK','A focused pilot before a larger rollout','The first release should prove that the content and maintenance process work.',steps([('Scope','One product family and a defined audience.'),('Publish','Approved source pages with useful internal links.'),('Validate','Fetch, render, index checks and answer sampling.'),('Decide','Expand, revise or stop using observed evidence.')])+table(['Work product','Acceptance criterion'],[['Claim register','Every pilot claim has a source, owner and review trigger.'],['Public page set','Essential facts are accessible and match approved product conditions.'],['Baseline and rerun','Same prompt cohort and settings, with citations and errors recorded.'],['Pilot review','Quality of enquiries or applications assessed alongside visibility.']]),'Case A / proposed pilot; no implementation or performance result claimed')
S('04 / CASE B · KOREAN INSURANCE COMPANY','The content existed across disconnected journeys','The audit raised questions about discovery, rendering and entity clarity.',table(['Reported finding','Why it matters','What must be verified'],[['The tested sitemap endpoint returned 404','Some discovery paths may be missing.','Alternative sitemap locations, internal links and indexed-page coverage.'],['Template placeholders appeared in fetched HTML','Important content may depend on rendering.','Raw versus rendered content, crawler access and representative URLs.'],['Corporate and transactional properties were split','The customer may reach the wrong product or service route.','Purpose of each domain, cross-links, duplicates and conversion paths.'],['English entity material was stale or shallow','Answers may reuse outdated facts or confuse business units.','Current first-party facts and actual responses on selected surfaces.']]),B)
S('04 / CASE B · KOREAN INSURANCE COMPANY','Clear relationships beat a forced domain merger','The proposed architecture preserves useful journeys while clarifying who provides what.','''<div class="network"><div class="network-root"><span>VERIFIED PROVIDER IDENTITY</span><h3>Korean Insurance Company</h3><p>Official name · business scope · current contact routes</p></div><div class="network-branches"><div><b>Corporate information</b><p>Governance, company facts and disclosures.</p></div><div><b>Product information</b><p>Coverage, conditions, exclusions and suitability.</p></div><div><b>Quote journey</b><p>Eligibility, application and conversion measurement.</p></div><div><b>Customer service</b><p>Claim steps, documentation and assistance.</p></div></div></div>'''+call('Assign each page a purpose and a maintained relationship. Use canonicals for duplicate or near-duplicate pages; keep genuinely different content independently discoverable.'),'Case B / architecture proposal; canonical guidance [S3]')
S('04 / CASE B · KOREAN INSURANCE COMPANY','A rendering fix starts with a comparison','A framework name alone cannot tell us what a search system can access.',cols('''<div class="code-panel"><span class="label">INITIAL RESPONSE / ILLUSTRATIVE</span><pre>&lt;h1&gt;Product information&lt;/h1&gt;\n&lt;div id="details"&gt;\n  {{ coverage.summary }}\n&lt;/div&gt;</pre><p>The key condition is absent from the response.</p></div>''','''<div class="code-panel good"><span class="label">PROPOSED ACCESSIBLE RESPONSE</span><pre>&lt;h1&gt;Product information&lt;/h1&gt;\n&lt;p&gt;Approved coverage summary&lt;/p&gt;\n&lt;a href="/terms/"&gt;\n  Conditions and exclusions\n&lt;/a&gt;</pre><p>Readers and compatible crawlers receive useful text.</p></div>''')+steps([('Compare','Raw HTML, rendered DOM and URL inspection.'),('Pilot','A small set of important pages.'),('Protect','Consistent content, release checks and rollback.'),('Measure','Access, index status and customer experience.')]),B+' / schematic example, not a captured client response')
S('04 / CASE B · KOREAN INSURANCE COMPANY','The same language can serve different buyers','Language expansion should follow a serviceable audience and a commercial route.',table(['Audience','Question to resolve','Content required','Operational dependency'],[['Resident customer','Can I buy and receive support in this language?','Eligibility, product guide, documentation and support details.','Actual language support and a working purchase path.'],['Investor or analyst','Which entity, business and period do these facts describe?','Dated corporate facts and clearly labelled reports.','Approved financial and corporate information.'],['Existing policyholder','How do I start a claim and what should I prepare?','Public process guide with boundaries and service routing.','An accurate claims process and available service channels.']])+call('Translate intent and service conditions. A translated corporate profile alone does not create a usable customer journey.'),'Case B / language and audience strategy; proposed execution')
S('05 / THE DELIVERY SYSTEM','The work connects evidence to a release','A common backlog brings SEO, content and AI-answer measurement together.',steps([('Evidence','Question, source page, current response and confidence.'),('Decision','Commercial priority, owner and acceptance test.'),('Release','Content or technical change with approved claims.'),('Observation','Access, citations, factual errors and customer actions.')])+cols(box('DELIVERABLE','A release-ready issue','Affected page, reproducible finding, proposed change, dependency and success check.'),box('DELIVERABLE','A decision-ready review','What shipped, what changed, what remains uncertain and what receives effort next.')),'Proposed fractional operating model')
S('05 / THE DELIVERY SYSTEM','Priorities change with the business constraint','Use the selector to see how the opening sprint changes.','''<div class="segmented" role="group" aria-label="Choose starting constraint"><button data-priority="access" class="selected" aria-pressed="true">Access problem</button><button data-priority="answers" aria-pressed="false">Answer problem</button><button data-priority="conversion" aria-pressed="false">Conversion problem</button></div><div class="priority-layout"><div class="priority-visual"><div class="axis-y">Business relevance ↑</div><div class="quadrants"><span>VALIDATE</span><span>PRIORITISE</span><span>DEFER</span><span>SCHEDULE</span><b id="priority-dot">1</b></div><div class="axis-x">Confidence in the diagnosis →</div></div><div id="priority-detail" aria-live="polite"></div></div>''','Illustrative prioritisation exercise / positions express judgment, not measured client scores')
S('05 / THE DELIVERY SYSTEM','Five controls before publishing a claim','One maintained evidence record should feed the page, markup and review process.',table(['Control','Required field','Why it earns its place'],[['Identity','Which legal entity, product and market?','Prevents mixing facts between related businesses.'],['Meaning','Claim, unit, scope and conditions.','Prevents a correct number being used in the wrong context.'],['Evidence','Approved source and effective date.','Gives reviewers a clear basis for verification.'],['Ownership','Content owner, reviewer and refresh trigger.','Turns freshness into a responsibility.'],['Consistency','Visible page, metadata and applicable markup agree.','Reduces contradictory representations of the same information.']])+call('A review date changes when content is actually reviewed. Automated date changes alone do not make an old claim current.'),'Derived from both cases / proposed claim governance')
S('05 / THE DELIVERY SYSTEM','Technical changes need a business reason','The implementation brief specifies the symptom, test and smallest useful fix.',table(['Symptom','Validate first','Potential response'],[['Key page cannot be reached','Status codes, access rules, CDN and internal links.','Repair the relevant access or linking issue.'],['Important text appears only after scripts run','Initial HTML versus rendered content on the target surface.','Server-render or statically publish essential content where justified.'],['Competing URLs carry the same material','Duplicate content, canonicals and redirects.','Consolidate duplicates with a tested migration path.'],['Facts differ across representations','Page copy, feeds, metadata and schema.','Update from a governed claim record.'],['Different languages serve the wrong intent','Audience, equivalent pages and service capability.','Create useful locale pages and appropriate language relationships.']]),'Proposed engineering brief / Google crawl and canonical guidance [S2, S3]')
S('06 / MEASUREMENT','A mention is not a citation','Keep each measure precise enough to support a decision.',table(['Measure','Operational definition','Useful interpretation'],[['Brand mention rate','Valid responses naming the brand ÷ all valid panel responses.','Presence in the sampled answers.'],['Owned-source citation rate','Valid responses linking an approved owned domain ÷ all valid panel responses.','First-party evidence used in the sampled answers.'],['Verified claim accuracy','Correct, checkable claims ÷ all checkable claims about the brand.','Quality of factual representation; record uncheckable claims separately.'],['Citation share within a defined set','Owned-domain citations ÷ citations to all tracked domains.','Relative presence for that panel and domain set only.'],['Qualified action rate','Qualified enquiries or completed applications ÷ relevant measured visits.','Commercial quality of the observable journey.']]),'Measurement definitions proposed for this programme; do not compare incompatible denominators')
S('06 / MEASUREMENT','A repeatable panel creates a usable baseline','The scope below is a proposed pilot design, not a historical audit result.','''<div class="panel-math"><div><strong>40</strong><span>prompts</span></div><b>×</b><div><strong>3</strong><span>selected surfaces</span></div><b>×</b><div><strong>2</strong><span>repeat runs</span></div><b>=</b><div class="accent"><strong>240</strong><span>attempted responses</span></div></div>'''+cols(box('STRATIFY','Intent and language','Split branded and unbranded questions. Cover trust, eligibility, comparison and action. Separate language cohorts.'),box('RECORD','The actual conditions','Save exact prompt, date, locale, surface, mode, full answer and linked URLs. Mark refusals, failures and no-answer responses.'),box('COMPARE','Like with like','Use new sessions and fixed settings where possible. Report counts and variation by cohort. Track model or product changes.'))+call('A synthetic prompt panel is a diagnostic sample. It is not the market’s query volume, audience reach or total share of demand.'),'Proposed research protocol adapted from the archive prompt kits')
S('06 / MEASUREMENT','The dashboard should tell us what to do next','Every signal needs a denominator, a source and a decision.',table(['Layer','What appears in the report','Decision it supports'],[['Delivery','Approved fixes shipped / committed fixes; ageing blockers.','Remove dependencies or narrow scope.'],['Technical access','Pilot URLs accessible / tested; index observations by URL.','Repair failed templates or discovery paths.'],['Answer quality','Owned citations / valid responses; correct / checkable claims.','Improve a specific source page or correct a factual gap.'],['Behaviour','Observed referral visits, engaged sessions and qualified actions.','Improve the landing page or next-step journey.'],['Commercial outcome','Qualified pipeline or applications with documented attribution.','Continue, modify or pause the investment.']])+call('Engine dashboards and prompt panels answer different questions. Keep their totals separate; missing referral data does not prove zero influence.'),'Proposed reporting model / Bing aggregated citation reporting [S4]')
S('06 / MEASUREMENT','A business case needs conservative arithmetic','Explore what must be true for a programme to cover its cost.','''<div class="economics"><div><span class="label">ILLUSTRATIVE INPUTS / MONTHLY</span><label>Programme cost <output id="cost-out"></output><input id="cost" type="range" min="3000" max="20000" step="500" value="10000"></label><label>Contribution per acquired customer <output id="margin-out"></output><input id="margin" type="range" min="250" max="5000" step="250" value="1000"></label><label>Qualified lead-to-customer rate <output id="close-out"></output><input id="close" type="range" min="5" max="50" step="1" value="20"></label></div><div class="calc-result"><span class="label">BREAK-EVEN REQUIREMENT</span><strong id="leads-out">50</strong><h3>additional qualified leads / month</h3><p id="customers-out"></p><div class="calc-rule">Cost ÷ (contribution per customer × close rate)</div><p class="small">S$ illustrative inputs. Contribution should be after variable costs and aligned to the same measurement horizon.</p></div></div>''','Scenario model, not a quote or forecast. Include implementation, tools and content costs. Attribution and time to conversion remain uncertain.')
S('07 / THE FIRST 90 DAYS','The first quarter builds an operating capability','Dates are indicative and depend on access, approvals and delivery capacity.','''<div class="roadmap"><div class="phase"><span>DAYS 1–15</span><h3>Establish the baseline</h3><p>Agree a product family, buyer intents and access. Revalidate audit signals and run the first panel.</p><b>Gate: evidence and scope accepted</b></div><div class="phase"><span>DAYS 16–30</span><h3>Remove critical barriers</h3><p>Address access or content faults. Approve claim records, release plan and page specifications.</p><b>Gate: release-ready backlog</b></div><div class="phase"><span>DAYS 31–60</span><h3>Publish the pilot</h3><p>Release a bounded page set. Validate content, tracking and relevant technical changes.</p><b>Gate: release quality accepted</b></div><div class="phase"><span>DAYS 61–90</span><h3>Review and expand</h3><p>Rerun the panel. Review qualified actions and blockers. Set the next-quarter investment.</p><b>Gate: scale, revise or pause</b></div></div>'''+call('The commitment is an accountable delivery process with explicit acceptance criteria. Rankings, citations and revenue are outcomes to measure, not guarantee.'),'Proposed roadmap adapted from both case workstreams')
S('07 / THE FIRST 90 DAYS','What you own at the end of the sprint','The deliverables remain usable by your internal team and existing partners.',table(['Deliverable','What is inside','Definition of done'],[['Baseline evidence pack','Crawl samples, prompt records and claim issues.','Results can be traced to a dated observation.'],['Prioritised implementation backlog','Scope, page, owner, dependency and acceptance test.','Each committed item is actionable.'],['Pilot content and technical briefs','Source-page templates, claim register and approved changes.','Pilot release passes agreed content and technical checks.'],['Measurement workspace','Definitions, tracked cohorts and dashboard specification.','The next measurement run can reproduce the method.'],['Operating playbook','Review cadence, escalation route and refresh rules.','Named owners can continue the programme.'],['Next-quarter recommendation','Observed progress, limits and options.','Sponsor can choose an investment with clear trade-offs.']]),'Proposed scope; exact outputs and production responsibilities confirmed in the statement of work')
S('08 / FRACTIONAL LEADERSHIP','One accountable lead across the work','I connect the commercial priority to the specialists who can deliver it.',cols('''<div class="ownership"><span class="label">FRACTIONAL LEAD</span><h3>Priority, evidence<br>and delivery decisions</h3><p>Own the programme backlog, brief the work, review quality, resolve trade-offs and report to the sponsor.</p><div>Works with your team and existing agencies</div></div>''',table(['Partner','Responsibility'],[['Business sponsor','Objectives, budget and decisions at the gates.'],['Product / subject expert','Facts, eligibility, conditions and source approval.'],['Content / localisation','Useful pages and audience-appropriate language.'],['Engineering / SEO','Access, templates, instrumentation and release checks.'],['Legal / compliance','Review claims where the business requires it.'],['Analytics / sales','Qualification definitions and downstream outcomes.']])),'Proposed responsibilities / production capacity is agreed explicitly')
S('08 / FRACTIONAL LEADERSHIP','Three ways to engage','Choose the level of ownership your team needs.',cols(box('DIAGNOSTIC / 2–3 WEEKS','Find the constraint','<b>For:</b> teams without a reliable baseline.<br><br><b>You receive:</b> evidence pack, prioritised gaps and a scoped pilot recommendation.<br><br><b>Client input:</b> access, product context and a sponsor.'),box('FOUNDATION / 90 DAYS','Deliver a bounded pilot','<b>For:</b> teams ready to improve a product or audience journey.<br><br><b>You receive:</b> coordinated delivery, QA, measurement and a next-quarter plan.<br><br><b>Client input:</b> content and engineering capacity.'),box('FRACTIONAL / ONGOING','Keep the programme moving','<b>For:</b> teams needing senior cross-functional ownership.<br><br><b>You receive:</b> weekly prioritisation, release reviews and monthly commercial reporting.<br><br><b>Client input:</b> agreed decision rights and team allocation.'))+call('Fees follow scope, markets, cadence and production responsibility. Tools, engineering, translation and specialist review are itemised in the proposal.'),'Engagement design adapted from supplied service specifications; no historic rate is presented as a current offer')
S('08 / FRACTIONAL LEADERSHIP','The mandate is wider than a content calendar','Prospective clients buy a clear owner for a connected business problem.',cols('''<div class="big-quote">“We have an SEO agency, content and technology teams.<br><em>Who connects the decisions?</em>”</div><p class="small">Illustrative buyer situation, not a client quotation.</p>''','''<ol class="numbered"><li><b>Translate the commercial problem</b><span>Choose the buyer journey and the business measure.</span></li><li><b>Make the work executable</b><span>Turn audit findings into scoped releases and clear ownership.</span></li><li><b>Challenge weak evidence</b><span>Separate observed results from assumptions and vendor claims.</span></li><li><b>Maintain the programme</b><span>Refresh facts, monitor changes and reallocate effort.</span></li></ol>''')+call('The fractional role complements specialist execution. It works best when the sponsor supplies access, authority and enough capacity to act.'),'Demand Journeys / proposed value proposition')
S('09 / DISCUSSION','Which buyer question<br>should you answer better?','Start with one market, one product family and one commercial objective.',cols('''<div class="closing-prompts"><p><span>01</span>Where do prospects hesitate or misunderstand the offer?</p><p><span>02</span>Which facts or pages should support the answer?</p><p><span>03</span>What customer action would make this work valuable?</p></div>''','''<div class="contact"><span class="label">FRACTIONAL GEO · AEO · SEO</span><h3>Demand Journeys</h3><p>Meng Liang Tan<br>Singapore · APAC and global engagements</p><a class="button" href="mailto:ml@demandjourneys.com?subject=GEO%20AEO%20SEO%20Discovery">Discuss your visibility challenge ↗</a><p><a href="mailto:ml@demandjourneys.com">ml@demandjourneys.com</a></p></div>'''),'Anonymised case studies and proposed services / scope agreed before delivery',cls='closing')
S('10 / EVIDENCE & SOURCES','What supports this presentation','Case evidence is historical. Platform guidance was checked for this draft.',table(['Reference','Basis','How it is used'],[['Case A / Case B','Supplied April 2026 financial-services audit bundle.','Anonymised observations, proposed remedies and measurement design. No client lift claimed.'],['[S1] Google AI features','<a href="https://developers.google.com/search/docs/appearance/ai-features">AI features and your website ↗</a>','SEO eligibility, useful text and consistency. No special AI markup requirement.'],['[S2] Google discovery','<a href="https://developers.google.com/search/docs/crawling-indexing/sitemaps/overview">Sitemap guidance ↗</a>','Sitemaps assist discovery; they are not indexed-page counts.'],['[S3] Google canonicals','<a href="https://developers.google.com/search/docs/crawling-indexing/consolidate-duplicate-urls">Consolidate duplicate URLs ↗</a>','Canonical relationships apply to duplicate or similar content.'],['[S4] Bing measurement','<a href="https://www.bing.com/webmasters/help/ai-performance-9f8e7d6c">AI Performance reporting ↗</a>','Aggregated citation evidence, distinct from commercial causality.'],['[S5] Google updates','<a href="https://developers.google.com/search/updates">Search documentation updates ↗</a>','FAQ rich results retired; llms.txt does not improve Google visibility.']]),'Guidance checked 15 October 2026 / no organisation names, original URLs or distinctive client identifiers included',note='The source archive contains inconsistent scores, simulated citation percentages, unmeasured performance claims and unsupported uplift projections. These are excluded. Official guidance replaces outdated implementation promises. Client-specific financial, legal and product claims are not reproduced.')
